python
def tallerKeycapsEvenKeyCensus(readings, k):
    a=readings
    out=[]
    out=[0]*len(a)
    stack=[]
    for i,x in enumerate(a):
        while stack and a[stack[-1]]<x:
            j=stack.pop()
            out[j]=i-j
        stack.append(i)
    return sum(x%2==0 for x in out)


java
class Solution {
  public int tallerKeycapsEvenKeyCensus(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int[]distance=new int[a.length];Deque<Integer>stack=new ArrayDeque<>();for(int i=0;i<a.length;i++){while(!stack.isEmpty()&&a[stack.peek()]<a[i]){int j=stack.pop();distance[j]=i-j;}stack.push(i);}for(int x:distance)out.add(x);}
    int answer=0;for(int x:out)if(x%2==0)answer++;return answer;
  }
}
